args.sql:
WITH scored AS (
 SELECT o.*, atmostransparency * (1 - humidityrate / 100.0) * (1 - 0.02 * windspeedms) AS aoi
 FROM observatories o
), classified AS (
 SELECT *, (aoi > 0.85 AND lunarstage IN ('New', 'First Quarter') AND lunardistdeg > 45 AND solarstatus IN ('Low', 'Moderate')) IS TRUE AS meets_oow
 FROM scored
)
SELECT meets_oow, COUNT(*) AS station_count, AVG(aoi) AS average_aoi, COUNT(*) FILTER (WHERE aoi IS NULL) AS missing_aoi
FROM classified GROUP BY meets_oow;

